```javascript
const http = require('node:http');
const { DatabaseSync } = require('node:sqlite');

const db = new DatabaseSync(process.env.BASE || 'rdv.db');

db.exec(`
  CREATE TABLE IF NOT EXISTS rendez_vous (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    telephone TEXT NOT NULL,
    date TEXT NOT NULL,
    service TEXT NOT NULL
  )
`);

const insertRendezVous = db.prepare(
  'INSERT INTO rendez_vous (nom, telephone, date, service) VALUES (?, ?, ?, ?)'
);
const getRendezVous = db.prepare(
  'SELECT id, nom, telephone, date, service FROM rendez_vous WHERE id = ?'
);
const listRendezVous = db.prepare(
  'SELECT id, nom, telephone, date, service FROM rendez_vous ORDER BY date ASC, id ASC'
);

function sendJson(res, statusCode, data) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

const server = http.createServer(async (req, res) => {
  const pathname = (req.url || '').split('?')[0];

  if (req.method === 'POST' && pathname === '/rendez-vous') {
    let body;

    try {
      let rawBody = '';
      for await (const chunk of req) rawBody += chunk;
      body = JSON.parse(rawBody);
    } catch {
      return sendJson(res, 400, { erreur: 'Le corps de la requête doit être un JSON valide.' });
    }

    const fields = ['nom', 'telephone', 'date', 'service'];
    const missingField = fields.find(
      (field) => body?.[field] === undefined || body[field] === null || body[field] === ''
    );

    if (missingField) {
      return sendJson(res, 400, { erreur: `Le champ « ${missingField} » est obligatoire.` });
    }

    const result = insertRendezVous.run(
      body.nom,
      body.telephone,
      body.date,
      body.service
    );
    const rendezVous = getRendezVous.get(Number(result.lastInsertRowid));

    return sendJson(res, 201, rendezVous);
  }

  if (req.method === 'GET' && pathname === '/rendez-vous') {
    return sendJson(res, 200, listRendezVous.all());
  }

  sendJson(res, 404, { erreur: 'Adresse introuvable.' });
});

server.listen(Number(process.env.PORT) || 3000);
