import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';

const dbPath = process.env.BASE || 'rdv.db';
const port = process.env.PORT || 3000;

const db = new DatabaseSync(dbPath);

db.exec(`
  CREATE TABLE IF NOT EXISTS rendez_vous (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    telephone TEXT NOT NULL,
    date TEXT NOT NULL,
    service TEXT NOT NULL
  )
`);

const insertStmt = db.prepare(`
  INSERT INTO rendez_vous (nom, telephone, date, service)
  VALUES (?, ?, ?, ?)
`);

const selectAllStmt = db.prepare(`
  SELECT id, nom, telephone, date, service
  FROM rendez_vous
  ORDER BY date ASC
`);

const sendJSON = (res, statusCode, data) => {
  res.writeHead(statusCode, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
};

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (url.pathname === '/rendez-vous') {
    if (req.method === 'GET') {
      const rows = selectAllStmt.all();
      return sendJSON(res, 200, rows);
    }

    if (req.method === 'POST') {
      let body = '';
      req.on('data', chunk => {
        body += chunk;
      });

      req.on('end', () => {
        let payload;
        try {
          payload = JSON.parse(body);
        } catch {
          return sendJSON(res, 400, { erreur: 'Corps de requête JSON invalide.' });
        }

        const { nom, telephone, date, service } = payload || {};

        if (
          !nom || typeof nom !== 'string' || !nom.trim() ||
          !telephone || typeof telephone !== 'string' || !telephone.trim() ||
          !date || typeof date !== 'string' || !date.trim() ||
          !service || typeof service !== 'string' || !service.trim()
        ) {
          return sendJSON(res, 400, { erreur: 'Tous les champs (nom, telephone, date, service) sont obligatoires.' });
        }

        const info = insertStmt.run(nom.trim(), telephone.trim(), date.trim(), service.trim());
        const createdId = Number(info.lastInsertRowid);

        return sendJSON(res, 201, {
          id: createdId,
          nom: nom.trim(),
          telephone: telephone.trim(),
          date: date.trim(),
          service: service.trim()
        });
      });
      return;
    }
  }

  sendJSON(res, 404, { erreur: 'Route non trouvée.' });
});

server.listen(port);
